        option_status: z.ZodOptional<z.ZodEnum<["feasible", "infeasible", "removed"]>>;
        /** 0.69.0 additive (MG, F1 spec §5). What a unitless count counts — see `CountNounSchema`. */
        count_noun: z.ZodOptional<z.ZodString>;
